132	  @Override
133	  public Result decodeRow(int rowNumber,
134	                          BitArray row,
135	                          Map<DecodeHintType,?> hints) throws NotFoundException, FormatException {
136	    // Rows can start with even pattern if previous rows had an odd number of patterns, so we try twice.
137	    this.startFromEven = false;
138	    try {
139	      return constructResult(decodeRow2pairs(rowNumber, row));
140	    } catch (NotFoundException e) {
141	      // OK
142	    }
143	
144	    this.startFromEven = true;
145	    return constructResult(decodeRow2pairs(rowNumber, row));
146	  }
