154	  // Not private for testing
155	  List<ExpandedPair> decodeRow2pairs(int rowNumber, BitArray row) throws NotFoundException {
156	    this.pairs.clear();
157	    boolean done = false;
158	    while (!done) {
159	      try {
160	        this.pairs.add(retrieveNextPair(row, this.pairs, rowNumber));
161	      } catch (NotFoundException nfe) {
162	        if (this.pairs.isEmpty()) {
163	          throw nfe;
164	        }
165	        // exit this loop when retrieveNextPair() fails and throws
166	        done = true;
167	      }
168	    }
169	
170	    if (checkChecksum() && isValidSequence(this.pairs, true)) {
171	      return this.pairs;
172	    }
173	
174	    boolean tryStackedDecode = !this.rows.isEmpty();
175	    storeRow(rowNumber); // TODO: deal with reversed rows
176	    if (tryStackedDecode) {
177	      // When the image is 180-rotated, then rows are sorted in wrong direction.
178	      // Try twice with both the directions.
179	      List<ExpandedPair> ps = checkRows(false);
180	      if (ps != null) {
181	        return ps;
182	      }
183	      ps = checkRows(true);
184	      if (ps != null) {
185	        return ps;
186	      }
187	    }
188	
189	    throw NotFoundException.getNotFoundInstance();
190	  }
191	
192	  private List<ExpandedPair> checkRows(boolean reverse) {
193	    // Limit number of rows we are checking
194	    // We use recursive algorithm with pure complexity and don't want it to take forever
195	    // Stacked barcode can have up to 11 rows, so 25 seems reasonable enough
196	    if (this.rows.size() > 25) {
197	      this.rows.clear();  // We will never have a chance to get result, so clear it
198	      return null;
199	    }
200	
201	    this.pairs.clear();
202	    if (reverse) {
203	      Collections.reverse(this.rows);
204	    }
205	
206	    List<ExpandedPair> ps = null;
207	    try {
208	      ps = checkRows(new ArrayList<>(), 0);
209	    } catch (NotFoundException e) {
210	      // OK
211	    }
212	
213	    if (reverse) {
214	      Collections.reverse(this.rows);
215	    }
216	
217	    return ps;
218	  }
219	
220	  // Try to construct a valid rows sequence
221	  // Recursion is used to implement backtracking
222	  private List<ExpandedPair> checkRows(List<ExpandedRow> collectedRows, int currentRow) throws NotFoundException {
223	    for (int i = currentRow; i < rows.size(); i++) {
224	      ExpandedRow row = rows.get(i);
225	      this.pairs.addAll(row.getPairs());
226	      int addSize = row.getPairs().size();
227	
228	      if (isValidSequence(this.pairs, false)) {
229	        if (checkChecksum()) {
230	          return this.pairs;
231	        }
232	        collectedRows.add(row);
233	        try {
234	          // Recursion: try to add more rows
235	          return checkRows(collectedRows, i + 1);
236	        } catch (NotFoundException e) {
237	          // We failed, try the next candidate
238	          collectedRows.remove(collectedRows.size() - 1);
239	          this.pairs.subList(this.pairs.size() - addSize, this.pairs.size()).clear();
240	        }
241	      } else {
242	        this.pairs.subList(this.pairs.size() - addSize, this.pairs.size()).clear();
243	      }
244	    }
245	
246	    throw NotFoundException.getNotFoundInstance();
247	  }
248	
249	  // Whether the pairs form a valid finder pattern sequence, either complete or a prefix
250	  private static boolean isValidSequence(List<ExpandedPair> pairs, boolean complete) {
251	
252	    for (int[] sequence : FINDER_PATTERN_SEQUENCES) {
253	      boolean sizeOk = (complete ? pairs.size() == sequence.length : pairs.size() <= sequence.length);
254	      if (sizeOk) {
255	        boolean stop = true;
256	        for (int j = 0; j < pairs.size(); j++) {
257	          if (pairs.get(j).getFinderPattern().getValue() != sequence[j]) {
258	            stop = false;
259	            break;
260	          }
261	        }
262	        if (stop) {
263	          return true;
264	        }
265	      }
266	    }
267	
268	    return false;
269	  }
270	
271	  // Whether the pairs, plus another pair of the specified type, would together
272	  // form a valid finder pattern sequence, either complete or partial
273	  private static boolean mayFollow(List<ExpandedPair> pairs, int value) {
274	
275	    if (pairs.isEmpty()) {
276	      return true;
277	    }
278	
279	    for (int[] sequence : FINDER_PATTERN_SEQUENCES) {
280	      if (pairs.size() + 1 <= sequence.length) {
281	        // the proposed sequence (i.e. pairs + value) would fit in this allowed sequence
282	        for (int i = pairs.size(); i < sequence.length; i++) {
283	          if (sequence[i] == value) {
284	            // we found our value in this allowed sequence, check to see if the elements preceding it match our existing
285	            // pairs; note our existing pairs may not be a full sequence (e.g. if processing a row in a stacked symbol)
286	            boolean matched = true;
287	            for (int j = 0; j < pairs.size(); j++) {
288	              int allowed = sequence[i - j - 1];
289	              int actual = pairs.get(pairs.size() - j - 1).getFinderPattern().getValue();
290	              if (allowed != actual) {
291	                matched = false;
292	                break;
293	              }
294	            }
295	            if (matched) {
296	              return true;
297	            }
298	          }
299	        }
300	      }
301	    }
302	
303	    // the proposed finder pattern sequence is illegal
304	    return false;
305	  }
