307	  private void storeRow(int rowNumber) {
308	    // Discard if duplicate above or below; otherwise insert in order by row number.
309	    int insertPos = 0;
310	    boolean prevIsSame = false;
311	    boolean nextIsSame = false;
312	    while (insertPos < this.rows.size()) {
313	      ExpandedRow erow = this.rows.get(insertPos);
314	      if (erow.getRowNumber() > rowNumber) {
315	        nextIsSame = erow.isEquivalent(this.pairs);
316	        break;
317	      }
318	      prevIsSame = erow.isEquivalent(this.pairs);
319	      insertPos++;
320	    }
321	    if (nextIsSame || prevIsSame) {
322	      return;
323	    }
324	
325	    // When the row was partially decoded (e.g. 2 pairs found instead of 3),
326	    // it will prevent us from detecting the barcode.
327	    // Try to merge partial rows
328	
329	    // Check whether the row is part of an already detected row
330	    if (isPartialRow(this.pairs, this.rows)) {
331	      return;
332	    }
333	
334	    this.rows.add(insertPos, new ExpandedRow(this.pairs, rowNumber));
335	
336	    removePartialRows(this.pairs, this.rows);
337	  }
338	
339	  // Remove all the rows that contains only specified pairs
340	  private static void removePartialRows(Collection<ExpandedPair> pairs, Collection<ExpandedRow> rows) {
341	    for (Iterator<ExpandedRow> iterator = rows.iterator(); iterator.hasNext();) {
342	      ExpandedRow r = iterator.next();
343	      if (r.getPairs().size() != pairs.size()) {
344	        boolean allFound = true;
345	        for (ExpandedPair p : r.getPairs()) {
346	          if (!pairs.contains(p)) {
347	            allFound = false;
348	            break;
349	          }
350	        }
351	        if (allFound) {
352	          // 'pairs' contains all the pairs from the row 'r'
353	          iterator.remove();
354	        }
355	      }
356	    }
357	  }
358	
359	  // Returns true when one of the rows already contains all the pairs
360	  private static boolean isPartialRow(Iterable<ExpandedPair> pairs, Iterable<ExpandedRow> rows) {
361	    for (ExpandedRow r : rows) {
362	      boolean allFound = true;
363	      for (ExpandedPair p : pairs) {
364	        boolean found = false;
365	        for (ExpandedPair pp : r.getPairs()) {
366	          if (p.equals(pp)) {
367	            found = true;
368	            break;
369	          }
370	        }
371	        if (!found) {
372	          allFound = false;
373	          break;
374	        }
375	      }
376	      if (allFound) {
377	        // the row 'r' contain all the pairs from 'pairs'
378	        return true;
379	      }
380	    }
381	    return false;
382	  }
