389	  // Not private for unit testing
390	  static Result constructResult(List<ExpandedPair> pairs) throws NotFoundException, FormatException {
391	    BitArray binary = BitArrayBuilder.buildBitArray(pairs);
392	
393	    AbstractExpandedDecoder decoder = AbstractExpandedDecoder.createDecoder(binary);
394	    String resultingString = decoder.parseInformation();
395	
396	    ResultPoint[] firstPoints = pairs.get(0).getFinderPattern().getResultPoints();
397	    ResultPoint[] lastPoints  = pairs.get(pairs.size() - 1).getFinderPattern().getResultPoints();
398	
399	    Result result = new Result(
400	          resultingString,
401	          null,
402	          new ResultPoint[]{firstPoints[0], firstPoints[1], lastPoints[0], lastPoints[1]},
403	          BarcodeFormat.RSS_EXPANDED
404	      );
405	    result.putMetadata(ResultMetadataType.SYMBOLOGY_IDENTIFIER, "]e0");
406	    return result;
407	  }
