409	  private boolean checkChecksum() {
410	    ExpandedPair firstPair = this.pairs.get(0);
411	    DataCharacter checkCharacter = firstPair.getLeftChar();
412	    DataCharacter firstCharacter = firstPair.getRightChar();
413	
414	    if (firstCharacter == null) {
415	      return false;
416	    }
417	
418	    int checksum = firstCharacter.getChecksumPortion();
419	    int s = 2;
420	
421	    for (int i = 1; i < this.pairs.size(); ++i) {
422	      ExpandedPair currentPair = this.pairs.get(i);
423	      checksum += currentPair.getLeftChar().getChecksumPortion();
424	      s++;
425	      DataCharacter currentRightChar = currentPair.getRightChar();
426	      if (currentRightChar != null) {
427	        checksum += currentRightChar.getChecksumPortion();
428	        s++;
429	      }
430	    }
431	
432	    checksum %= 211;
433	
434	    int checkCharacterValue = 211 * (s - 4) + checksum;
435	
436	    return checkCharacterValue == checkCharacter.getValue();
437	  }
