439	  private static int getNextSecondBar(BitArray row, int initialPos) {
440	    int currentPos;
441	    if (row.get(initialPos)) {
442	      currentPos = row.getNextUnset(initialPos);
443	      currentPos = row.getNextSet(currentPos);
444	    } else {
445	      currentPos = row.getNextSet(initialPos);
446	      currentPos = row.getNextUnset(currentPos);
447	    }
448	    return currentPos;
449	  }
450	
451	  // not private for testing
452	  ExpandedPair retrieveNextPair(BitArray row, List<ExpandedPair> previousPairs, int rowNumber)
453	      throws NotFoundException {
454	    boolean isOddPattern  = previousPairs.size() % 2 == 0;
455	    if (startFromEven) {
456	      isOddPattern = !isOddPattern;
457	    }
458	
459	    FinderPattern pattern;
460	    DataCharacter leftChar = null;
461	
462	    boolean keepFinding = true;
463	    int forcedOffset = -1;
464	    do {
465	      this.findNextPair(row, previousPairs, forcedOffset);
466	      pattern = parseFoundFinderPattern(row, rowNumber, isOddPattern, previousPairs);
467	      if (pattern == null) {
468	        forcedOffset = getNextSecondBar(row, this.startEnd[0]); // probable false positive, keep looking
469	      } else {
470	        try {
471	          leftChar  = this.decodeDataCharacter(row, pattern, isOddPattern, true);
472	          keepFinding = false;
473	        } catch (NotFoundException ignored) {
474	          forcedOffset = getNextSecondBar(row, this.startEnd[0]); // probable false positive, keep looking
475	        }
476	      }
477	    } while (keepFinding);
478	
479	    // When stacked symbol is split over multiple rows, there's no way to guess if this pair can be last or not.
480	    // boolean mayBeLast = checkPairSequence(previousPairs, pattern);
481	
482	    if (!previousPairs.isEmpty() && previousPairs.get(previousPairs.size() - 1).mustBeLast()) {
483	      throw NotFoundException.getNotFoundInstance();
484	    }
485	
486	    DataCharacter rightChar;
487	    try {
488	      rightChar = this.decodeDataCharacter(row, pattern, isOddPattern, false);
489	    } catch (NotFoundException ignored) {
490	      rightChar = null;
491	    }
492	    return new ExpandedPair(leftChar, rightChar, pattern);
493	  }
494	
495	  private void findNextPair(BitArray row, List<ExpandedPair> previousPairs, int forcedOffset)
496	      throws NotFoundException {
497	    int[] counters = this.getDecodeFinderCounters();
498	    counters[0] = 0;
499	    counters[1] = 0;
500	    counters[2] = 0;
501	    counters[3] = 0;
502	
503	    int width = row.getSize();
504	
505	    int rowOffset;
506	    if (forcedOffset >= 0) {
507	      rowOffset = forcedOffset;
508	    } else if (previousPairs.isEmpty()) {
509	      rowOffset = 0;
510	    } else {
511	      ExpandedPair lastPair = previousPairs.get(previousPairs.size() - 1);
512	      rowOffset = lastPair.getFinderPattern().getStartEnd()[1];
513	    }
514	    boolean searchingEvenPair = previousPairs.size() % 2 != 0;
515	    if (startFromEven) {
516	      searchingEvenPair = !searchingEvenPair;
517	    }
518	
519	    boolean isWhite = false;
520	    while (rowOffset < width) {
521	      isWhite = !row.get(rowOffset);
522	      if (!isWhite) {
523	        break;
524	      }
525	      rowOffset++;
526	    }
527	
528	    int counterPosition = 0;
529	    int patternStart = rowOffset;
530	    for (int x = rowOffset; x < width; x++) {
531	      if (row.get(x) != isWhite) {
532	        counters[counterPosition]++;
533	      } else {
534	        if (counterPosition == 3) {
535	          if (searchingEvenPair) {
536	            reverseCounters(counters);
537	          }
538	
539	          if (isFinderPattern(counters)) {
540	            this.startEnd[0] = patternStart;
541	            this.startEnd[1] = x;
542	            return;
543	          }
544	
545	          if (searchingEvenPair) {
546	            reverseCounters(counters);
547	          }
548	
549	          patternStart += counters[0] + counters[1];
550	          counters[0] = counters[2];
551	          counters[1] = counters[3];
552	          counters[2] = 0;
553	          counters[3] = 0;
554	          counterPosition--;
555	        } else {
556	          counterPosition++;
557	        }
558	        counters[counterPosition] = 1;
559	        isWhite = !isWhite;
560	      }
561	    }
562	    throw NotFoundException.getNotFoundInstance();
563	  }
564	
565	  private static void reverseCounters(int [] counters) {
566	    int length = counters.length;
567	    for (int i = 0; i < length / 2; ++i) {
568	      int tmp = counters[i];
569	      counters[i] = counters[length - i - 1];
570	      counters[length - i - 1] = tmp;
571	    }
572	  }
573	
574	  private FinderPattern parseFoundFinderPattern(BitArray row,
575	                                                int rowNumber,
576	                                                boolean oddPattern,
577	                                                List<ExpandedPair> previousPairs) {
578	    // Actually we found elements 2-5.
579	    int firstCounter;
580	    int start;
581	    int end;
582	
583	    if (oddPattern) {
584	      // If pattern number is odd, we need to locate element 1 *before* the current block.
585	
586	      int firstElementStart = this.startEnd[0] - 1;
587	      // Locate element 1
588	      while (firstElementStart >= 0 && !row.get(firstElementStart)) {
589	        firstElementStart--;
590	      }
591	
592	      firstElementStart++;
593	      firstCounter = this.startEnd[0] - firstElementStart;
594	      start = firstElementStart;
595	      end = this.startEnd[1];
596	
597	    } else {
598	      // If pattern number is even, the pattern is reversed, so we need to locate element 1 *after* the current block.
599	
600	      start = this.startEnd[0];
601	
602	      end = row.getNextUnset(this.startEnd[1] + 1);
603	      firstCounter = end - this.startEnd[1];
604	    }
605	
606	    // Make 'counters' hold 1-4
607	    int [] counters = this.getDecodeFinderCounters();
608	    System.arraycopy(counters, 0, counters, 1, counters.length - 1);
609	
610	    counters[0] = firstCounter;
611	    int value;
612	    try {
613	      value = parseFinderValue(counters, FINDER_PATTERNS);
614	    } catch (NotFoundException ignored) {
615	      return null;
616	    }
617	
618	    // Check that the pattern type that we *think* we found can exist as part of a valid sequence of finder patterns.
619	    if (!mayFollow(previousPairs, value)) {
620	      return null;
621	    }
622	
623	    // Check that the finder pattern that we *think* we found is not too far from where we would expect to find it,
624	    // given that finder patterns are 15 modules wide and the data characters between them are 17 modules wide.
625	    if (!previousPairs.isEmpty()) {
626	      ExpandedPair prev = previousPairs.get(previousPairs.size() - 1);
627	      int prevStart = prev.getFinderPattern().getStartEnd()[0];
628	      int prevEnd = prev.getFinderPattern().getStartEnd()[1];
629	      int prevWidth = prevEnd - prevStart;
630	      float charWidth = (prevWidth / FINDER_PATTERN_MODULES) * DATA_CHARACTER_MODULES;
631	      float minX = prevEnd + (2 * charWidth * (1 - MAX_FINDER_PATTERN_DISTANCE_VARIANCE));
632	      float maxX = prevEnd + (2 * charWidth * (1 + MAX_FINDER_PATTERN_DISTANCE_VARIANCE));
633	      if (start < minX || start > maxX) {
634	        return null;
635	      }
636	    }
637	
638	    return new FinderPattern(value, new int[] {start, end}, start, end, rowNumber);
639	  }
640	
641	  DataCharacter decodeDataCharacter(BitArray row,
642	                                    FinderPattern pattern,
643	                                    boolean isOddPattern,
644	                                    boolean leftChar) throws NotFoundException {
645	    int[] counters = this.getDataCharacterCounters();
646	    Arrays.fill(counters, 0);
647	
648	    if (leftChar) {
649	      recordPatternInReverse(row, pattern.getStartEnd()[0], counters);
650	    } else {
651	      recordPattern(row, pattern.getStartEnd()[1], counters);
652	      // reverse it
653	      for (int i = 0, j = counters.length - 1; i < j; i++, j--) {
654	        int temp = counters[i];
655	        counters[i] = counters[j];
656	        counters[j] = temp;
657	      }
658	    } //counters[] has the pixels of the module
659	
660	    int numModules = 17; //left and right data characters have all the same length
661	    float elementWidth = MathUtils.sum(counters) / (float) numModules;
662	
663	    // Sanity check: element width for pattern and the character should match
664	    float expectedElementWidth = (pattern.getStartEnd()[1] - pattern.getStartEnd()[0]) / 15.0f;
665	    if (Math.abs(elementWidth - expectedElementWidth) / expectedElementWidth > 0.3f) {
666	      throw NotFoundException.getNotFoundInstance();
667	    }
668	
669	    int[] oddCounts = this.getOddCounts();
670	    int[] evenCounts = this.getEvenCounts();
671	    float[] oddRoundingErrors = this.getOddRoundingErrors();
672	    float[] evenRoundingErrors = this.getEvenRoundingErrors();
673	
674	    for (int i = 0; i < counters.length; i++) {
675	      float value = 1.0f * counters[i] / elementWidth;
676	      int count = (int) (value + 0.5f); // Round
677	      if (count < 1) {
678	        if (value < 0.3f) {
679	          throw NotFoundException.getNotFoundInstance();
680	        }
681	        count = 1;
682	      } else if (count > 8) {
683	        if (value > 8.7f) {
684	          throw NotFoundException.getNotFoundInstance();
685	        }
686	        count = 8;
687	      }
688	      int offset = i / 2;
689	      if ((i & 0x01) == 0) {
690	        oddCounts[offset] = count;
691	        oddRoundingErrors[offset] = value - count;
692	      } else {
693	        evenCounts[offset] = count;
694	        evenRoundingErrors[offset] = value - count;
695	      }
696	    }
697	
698	    adjustOddEvenCounts(numModules);
699	
700	    int weightRowNumber = 4 * pattern.getValue() + (isOddPattern ? 0 : 2) + (leftChar ? 0 : 1) - 1;
701	
702	    int oddSum = 0;
703	    int oddChecksumPortion = 0;
704	    for (int i = oddCounts.length - 1; i >= 0; i--) {
705	      if (isNotA1left(pattern, isOddPattern, leftChar)) {
706	        int weight = WEIGHTS[weightRowNumber][2 * i];
707	        oddChecksumPortion += oddCounts[i] * weight;
708	      }
709	      oddSum += oddCounts[i];
710	    }
711	    int evenChecksumPortion = 0;
712	    for (int i = evenCounts.length - 1; i >= 0; i--) {
713	      if (isNotA1left(pattern, isOddPattern, leftChar)) {
714	        int weight = WEIGHTS[weightRowNumber][2 * i + 1];
715	        evenChecksumPortion += evenCounts[i] * weight;
716	      }
717	    }
718	    int checksumPortion = oddChecksumPortion + evenChecksumPortion;
719	
720	    if ((oddSum & 0x01) != 0 || oddSum > 13 || oddSum < 4) {
721	      throw NotFoundException.getNotFoundInstance();
722	    }
723	
724	    int group = (13 - oddSum) / 2;
725	    int oddWidest = SYMBOL_WIDEST[group];
726	    int evenWidest = 9 - oddWidest;
727	    int vOdd = RSSUtils.getRSSvalue(oddCounts, oddWidest, true);
728	    int vEven = RSSUtils.getRSSvalue(evenCounts, evenWidest, false);
729	    int tEven = EVEN_TOTAL_SUBSET[group];
730	    int gSum = GSUM[group];
731	    int value = vOdd * tEven + vEven + gSum;
732	
733	    return new DataCharacter(value, checksumPortion);
734	  }
735	
736	  private static boolean isNotA1left(FinderPattern pattern, boolean isOddPattern, boolean leftChar) {
737	    // A1: pattern.getValue is 0 (A), and it's an oddPattern, and it is a left char
738	    return !(pattern.getValue() == 0 && isOddPattern && leftChar);
739	  }
740	
741	  private void adjustOddEvenCounts(int numModules) throws NotFoundException {
742	
743	    int oddSum = MathUtils.sum(this.getOddCounts());
744	    int evenSum = MathUtils.sum(this.getEvenCounts());
745	
746	    boolean incrementOdd = false;
747	    boolean decrementOdd = false;
748	
749	    if (oddSum > 13) {
750	      decrementOdd = true;
751	    } else if (oddSum < 4) {
752	      incrementOdd = true;
753	    }
754	    boolean incrementEven = false;
755	    boolean decrementEven = false;
756	    if (evenSum > 13) {
757	      decrementEven = true;
758	    } else if (evenSum < 4) {
759	      incrementEven = true;
760	    }
761	
762	    int mismatch = oddSum + evenSum - numModules;
763	    boolean oddParityBad = (oddSum & 0x01) == 1;
764	    boolean evenParityBad = (evenSum & 0x01) == 0;
765	    switch (mismatch) {
766	      case 1:
767	        if (oddParityBad) {
768	          if (evenParityBad) {
769	            throw NotFoundException.getNotFoundInstance();
770	          }
771	          decrementOdd = true;
772	        } else {
773	          if (!evenParityBad) {
774	            throw NotFoundException.getNotFoundInstance();
775	          }
776	          decrementEven = true;
777	        }
778	        break;
779	      case -1:
780	        if (oddParityBad) {
781	          if (evenParityBad) {
782	            throw NotFoundException.getNotFoundInstance();
783	          }
784	          incrementOdd = true;
785	        } else {
786	          if (!evenParityBad) {
787	            throw NotFoundException.getNotFoundInstance();
788	          }
789	          incrementEven = true;
790	        }
791	        break;
792	      case 0:
793	        if (oddParityBad) {
794	          if (!evenParityBad) {
795	            throw NotFoundException.getNotFoundInstance();
796	          }
797	          // Both bad
798	          if (oddSum < evenSum) {
799	            incrementOdd = true;
800	            decrementEven = true;
801	          } else {
802	            decrementOdd = true;
803	            incrementEven = true;
804	          }
805	        } else {
806	          if (evenParityBad) {
807	            throw NotFoundException.getNotFoundInstance();
808	          }
809	          // Nothing to do!
810	        }
811	        break;
812	      default:
813	        throw NotFoundException.getNotFoundInstance();
814	    }
815	
816	    if (incrementOdd) {
817	      if (decrementOdd) {
818	        throw NotFoundException.getNotFoundInstance();
819	      }
820	      increment(this.getOddCounts(), this.getOddRoundingErrors());
821	    }
822	    if (decrementOdd) {
823	      decrement(this.getOddCounts(), this.getOddRoundingErrors());
824	    }
825	    if (incrementEven) {
826	      if (decrementEven) {
827	        throw NotFoundException.getNotFoundInstance();
828	      }
829	      increment(this.getEvenCounts(), this.getOddRoundingErrors());
830	    }
831	    if (decrementEven) {
832	      decrement(this.getEvenCounts(), this.getEvenRoundingErrors());
833	    }
834	  }
