30	/**
31	 * <p>Implements decoding of the ITF format, or Interleaved Two of Five.</p>
32	 *
33	 * <p>This Reader will scan ITF barcodes of certain lengths only.
34	 * At the moment it reads length 6, 8, 10, 12, 14, 16, 18, 20, 24, and 44 as these have appeared "in the wild". Not all
35	 * lengths are scanned, especially shorter ones, to avoid false positives. This in turn is due to a lack of
36	 * required checksum function.</p>
37	 *
38	 * <p>The checksum is optional and is not applied by this Reader. The consumer of the decoded
39	 * value will have to apply a checksum if required.</p>
40	 *
41	 * <p><a href="http://en.wikipedia.org/wiki/Interleaved_2_of_5">http://en.wikipedia.org/wiki/Interleaved_2_of_5</a>
42	 * is a great reference for Interleaved 2 of 5 information.</p>
43	 *
44	 * @author kevin.osullivan@sita.aero, SITA Lab.
45	 */
46	public final class ITFReader extends OneDReader {
47	
48	  private static final float MAX_AVG_VARIANCE = 0.38f;
49	  private static final float MAX_INDIVIDUAL_VARIANCE_2X = 0.5f; // 2x wide lines -> stricter
50	  private static final float MAX_INDIVIDUAL_VARIANCE_3X = 0.75f; // 3x wide lines -> less strict
51	
52	  private static final int W = 3; // Pixel width of a 3x wide line
53	  private static final int w = 2; // Pixel width of a 2x wide line
54	  private static final int N = 1; // Pixel width of a narrow line
55	
56	  /** Valid ITF lengths. Anything longer than the largest value is also allowed. */
57	  private static final int[] DEFAULT_ALLOWED_LENGTHS = {6, 8, 10, 12, 14};
58	
59	  // Stores the actual narrow line width of the image being decoded.
60	  private int narrowLineWidth = -1;
61	
62	  /**
63	   * Start/end guard pattern.
64	   *
65	   * Note: The end pattern is reversed because the row is reversed before
66	   * searching for the END_PATTERN
67	   */
68	  private static final int[] START_PATTERN = {N, N, N, N};
69	  private static final int[][] END_PATTERN_REVERSED = {
70	      {N, N, w}, // 2x
71	      {N, N, W}  // 3x
72	  };
73	
74	  // See ITFWriter.PATTERNS
75	
76	  /**
77	   * Patterns of Wide / Narrow lines to indicate each digit
78	   */
79	  private static final int[][] PATTERNS = {
80	      {N, N, w, w, N}, // 0
81	      {w, N, N, N, w}, // 1
82	      {N, w, N, N, w}, // 2
83	      {w, w, N, N, N}, // 3
84	      {N, N, w, N, w}, // 4
85	      {w, N, w, N, N}, // 5
86	      {N, w, w, N, N}, // 6
87	      {N, N, N, w, w}, // 7
88	      {w, N, N, w, N}, // 8
89	      {N, w, N, w, N}, // 9
90	      {N, N, W, W, N}, // 0
91	      {W, N, N, N, W}, // 1
92	      {N, W, N, N, W}, // 2
93	      {W, W, N, N, N}, // 3
94	      {N, N, W, N, W}, // 4
95	      {W, N, W, N, N}, // 5
96	      {N, W, W, N, N}, // 6
97	      {N, N, N, W, W}, // 7
98	      {W, N, N, W, N}, // 8
99	      {N, W, N, W, N}  // 9
100	  };
101	
102	  @Override
103	  public Result decodeRow(int rowNumber, BitArray row, Map<DecodeHintType,?> hints)
104	      throws FormatException, NotFoundException {
105	
106	    // Find out where the Middle section (payload) starts & ends
107	    int[] startRange = decodeStart(row);
108	    int[] endRange = decodeEnd(row);
109	
110	    StringBuilder result = new StringBuilder(20);
111	    decodeMiddle(row, startRange[1], endRange[0], result);
112	    String resultString = result.toString();
113	
114	    int[] allowedLengths = null;
115	    if (hints != null) {
116	      allowedLengths = (int[]) hints.get(DecodeHintType.ALLOWED_LENGTHS);
117	
118	    }
119	    if (allowedLengths == null) {
120	      allowedLengths = DEFAULT_ALLOWED_LENGTHS;
121	    }
122	
123	    // To avoid false positives with 2D barcodes (and other patterns), make
124	    // an assumption that the decoded string must be a 'standard' length if it's short
125	    int length = resultString.length();
126	    boolean lengthOK = false;
127	    int maxAllowedLength = 0;
128	    for (int allowedLength : allowedLengths) {
129	      if (length == allowedLength) {
130	        lengthOK = true;
131	        break;
132	      }
133	      if (allowedLength > maxAllowedLength) {
134	        maxAllowedLength = allowedLength;
135	      }
136	    }
137	    if (!lengthOK && length > maxAllowedLength) {
138	      lengthOK = true;
139	    }
140	    if (!lengthOK) {
141	      throw FormatException.getFormatInstance();
142	    }
143	
144	    Result resultObject = new Result(
145	        resultString,
146	        null, // no natural byte representation for these barcodes
147	        new ResultPoint[] {new ResultPoint(startRange[1], rowNumber),
148	                           new ResultPoint(endRange[0], rowNumber)},
149	        BarcodeFormat.ITF);
150	    resultObject.putMetadata(ResultMetadataType.SYMBOLOGY_IDENTIFIER, "]I0");
151	    return resultObject;
152	  }
153	
154	  /**
155	   * @param row          row of black/white values to search
156	   * @param payloadStart offset of start pattern
157	   * @param resultString {@link StringBuilder} to append decoded chars to
158	   * @throws NotFoundException if decoding could not complete successfully
159	   */
160	  private static void decodeMiddle(BitArray row,
161	                                   int payloadStart,
162	                                   int payloadEnd,
163	                                   StringBuilder resultString) throws NotFoundException {
164	
165	    // Digits are interleaved in pairs - 5 black lines for one digit, and the
166	    // 5
167	    // interleaved white lines for the second digit.
168	    // Therefore, need to scan 10 lines and then
169	    // split these into two arrays
170	    int[] counterDigitPair = new int[10];
171	    int[] counterBlack = new int[5];
172	    int[] counterWhite = new int[5];
173	
174	    while (payloadStart < payloadEnd) {
175	
176	      // Get 10 runs of black/white.
177	      recordPattern(row, payloadStart, counterDigitPair);
178	      // Split them into each array
179	      for (int k = 0; k < 5; k++) {
180	        int twoK = 2 * k;
181	        counterBlack[k] = counterDigitPair[twoK];
182	        counterWhite[k] = counterDigitPair[twoK + 1];
183	      }
184	
185	      int bestMatch = decodeDigit(counterBlack);
186	      resultString.append((char) ('0' + bestMatch));
187	      bestMatch = decodeDigit(counterWhite);
188	      resultString.append((char) ('0' + bestMatch));
189	
190	      for (int counterDigit : counterDigitPair) {
191	        payloadStart += counterDigit;
192	      }
193	    }
194	  }
195	
196	  /**
197	   * Identify where the start of the middle / payload section starts.
198	   *
199	   * @param row row of black/white values to search
200	   * @return Array, containing index of start of 'start block' and end of
201	   *         'start block'
202	   */
203	  private int[] decodeStart(BitArray row) throws NotFoundException {
204	    int endStart = skipWhiteSpace(row);
205	    int[] startPattern = findGuardPattern(row, endStart, START_PATTERN);
206	
207	    // Determine the width of a narrow line in pixels. We can do this by
208	    // getting the width of the start pattern and dividing by 4 because its
209	    // made up of 4 narrow lines.
210	    this.narrowLineWidth = (startPattern[1] - startPattern[0]) / 4;
211	
212	    validateQuietZone(row, startPattern[0]);
213	
214	    return startPattern;
215	  }
216	
217	  /**
218	   * The start & end patterns must be pre/post fixed by a quiet zone. This
219	   * zone must be at least 10 times the width of a narrow line.  Scan back until
220	   * we either get to the start of the barcode or match the necessary number of
221	   * quiet zone pixels.
222	   *
223	   * Note: Its assumed the row is reversed when using this method to find
224	   * quiet zone after the end pattern.
225	   *
226	   * ref: http://www.barcode-1.net/i25code.html
227	   *
228	   * @param row bit array representing the scanned barcode.
229	   * @param startPattern index into row of the start or end pattern.
230	   * @throws NotFoundException if the quiet zone cannot be found
231	   */
232	  private void validateQuietZone(BitArray row, int startPattern) throws NotFoundException {
233	
234	    int quietCount = this.narrowLineWidth * 10;  // expect to find this many pixels of quiet zone
235	
236	    // if there are not so many pixel at all let's try as many as possible
237	    quietCount = Math.min(quietCount, startPattern);
238	
239	    for (int i = startPattern - 1; quietCount > 0 && i >= 0; i--) {
240	      if (row.get(i)) {
241	        break;
242	      }
243	      quietCount--;
244	    }
245	    if (quietCount != 0) {
246	      // Unable to find the necessary number of quiet zone pixels.
247	      throw NotFoundException.getNotFoundInstance();
248	    }
249	  }
250	
251	  /**
252	   * Skip all whitespace until we get to the first black line.
253	   *
254	   * @param row row of black/white values to search
255	   * @return index of the first black line.
256	   * @throws NotFoundException Throws exception if no black lines are found in the row
257	   */
258	  private static int skipWhiteSpace(BitArray row) throws NotFoundException {
259	    int width = row.getSize();
260	    int endStart = row.getNextSet(0);
261	    if (endStart == width) {
262	      throw NotFoundException.getNotFoundInstance();
263	    }
264	
265	    return endStart;
266	  }
267	
268	  /**
269	   * Identify where the end of the middle / payload section ends.
270	   *
271	   * @param row row of black/white values to search
272	   * @return Array, containing index of start of 'end block' and end of 'end
273	   *         block'
274	   */
275	  private int[] decodeEnd(BitArray row) throws NotFoundException {
276	
277	    // For convenience, reverse the row and then
278	    // search from 'the start' for the end block
279	    row.reverse();
280	    try {
281	      int endStart = skipWhiteSpace(row);
282	      int[] endPattern;
283	      try {
284	        endPattern = findGuardPattern(row, endStart, END_PATTERN_REVERSED[0]);
285	      } catch (NotFoundException nfe) {
286	        endPattern = findGuardPattern(row, endStart, END_PATTERN_REVERSED[1]);
287	      }
288	
289	      // The start & end patterns must be pre/post fixed by a quiet zone. This
290	      // zone must be at least 10 times the width of a narrow line.
291	      // ref: http://www.barcode-1.net/i25code.html
292	      validateQuietZone(row, endPattern[0]);
293	
294	      // Now recalculate the indices of where the 'endblock' starts & stops to
295	      // accommodate
296	      // the reversed nature of the search
297	      int temp = endPattern[0];
298	      endPattern[0] = row.getSize() - endPattern[1];
299	      endPattern[1] = row.getSize() - temp;
300	
301	      return endPattern;
302	    } finally {
303	      // Put the row back the right way.
304	      row.reverse();
305	    }
306	  }
307	
308	  /**
309	   * @param row       row of black/white values to search
310	   * @param rowOffset position to start search
311	   * @param pattern   pattern of counts of number of black and white pixels that are
312	   *                  being searched for as a pattern
313	   * @return start/end horizontal offset of guard pattern, as an array of two
314	   *         ints
315	   * @throws NotFoundException if pattern is not found
316	   */
317	  private static int[] findGuardPattern(BitArray row,
318	                                        int rowOffset,
319	                                        int[] pattern) throws NotFoundException {
320	    int patternLength = pattern.length;
321	    int[] counters = new int[patternLength];
322	    int width = row.getSize();
323	    boolean isWhite = false;
324	
325	    int counterPosition = 0;
326	    int patternStart = rowOffset;
327	    for (int x = rowOffset; x < width; x++) {
328	      if (row.get(x) != isWhite) {
329	        counters[counterPosition]++;
330	      } else {
331	        if (counterPosition == patternLength - 1) {
332	          if (patternMatchVariance(counters, pattern, MAX_INDIVIDUAL_VARIANCE_2X) < MAX_AVG_VARIANCE) {
333	            return new int[]{patternStart, x};
334	          }
335	          patternStart += counters[0] + counters[1];
336	          System.arraycopy(counters, 2, counters, 0, counterPosition - 1);
337	          counters[counterPosition - 1] = 0;
338	          counters[counterPosition] = 0;
339	          counterPosition--;
340	        } else {
341	          counterPosition++;
342	        }
343	        counters[counterPosition] = 1;
344	        isWhite = !isWhite;
345	      }
346	    }
347	    throw NotFoundException.getNotFoundInstance();
348	  }
349	
350	  /**
351	   * Attempts to decode a sequence of ITF black/white lines into single
352	   * digit.
353	   *
354	   * @param counters the counts of runs of observed black/white/black/... values
355	   * @return The decoded digit
356	   * @throws NotFoundException if digit cannot be decoded
357	   */
358	  private static int decodeDigit(int[] counters) throws NotFoundException {
359	    float bestVariance = MAX_AVG_VARIANCE; // worst variance we'll accept
360	    int bestMatch = -1;
361	    int max = PATTERNS.length;
362	    for (int i = 0; i < max; i++) {
363	      int[] pattern = PATTERNS[i];
364	      float maxVariance = (i <= 9 ? MAX_INDIVIDUAL_VARIANCE_2X : MAX_INDIVIDUAL_VARIANCE_3X);
365	      float variance = patternMatchVariance(counters, pattern, maxVariance);
366	      if (variance < bestVariance) {
367	        bestVariance = variance;
368	        bestMatch = i;
369	      } else if (variance == bestVariance) {
370	        // if we find a second 'best match' with the same variance, we can not reliably report to have a suitable match
371	        bestMatch = -1;
372	      }
373	    }
374	    if (bestMatch >= 0) {
375	      return bestMatch % 10;
376	    } else {
377	      throw NotFoundException.getNotFoundInstance();
378	    }
379	  }
380	
381	}
