17	package com.google.zxing.common.reedsolomon;
18	
19	/**
20	 * <p>Implements Reed-Solomon decoding, as the name implies.</p>
21	 *
22	 * <p>The algorithm will not be explained here, but the following references were helpful
23	 * in creating this implementation:</p>
24	 *
25	 * <ul>
26	 * <li>Bruce Maggs.
27	 * <a href="http://www.cs.cmu.edu/afs/cs.cmu.edu/project/pscico-guyb/realworld/www/rs_decode.ps">
28	 * "Decoding Reed-Solomon Codes"</a> (see discussion of Forney's Formula)</li>
29	 * <li>J.I. Hall. <a href="www.mth.msu.edu/~jhall/classes/codenotes/GRS.pdf">
30	 * "Chapter 5. Generalized Reed-Solomon Codes"</a>
31	 * (see discussion of Euclidean algorithm)</li>
32	 * </ul>
33	 *
34	 * <p>Much credit is due to William Rucklidge since portions of this code are an indirect
35	 * port of his C++ Reed-Solomon implementation.</p>
36	 *
37	 * @author Sean Owen
38	 * @author William Rucklidge
39	 * @author sanfordsquires
40	 */
41	public final class ReedSolomonDecoder {
42	
43	  private final GenericGF field;
44	
45	  public ReedSolomonDecoder(GenericGF field) {
46	    this.field = field;
47	  }
48	
49	  /**
50	   * <p>Decodes given set of received codewords, which include both data and error-correction
51	   * codewords. Really, this means it uses Reed-Solomon to detect and correct errors, in-place,
52	   * in the input.</p>
53	   *
54	   * @param received data and error-correction codewords
55	   * @param twoS number of error-correction codewords available
56	   * @throws ReedSolomonException if decoding fails for any reason
57	   */
58	  public void decode(int[] received, int twoS) throws ReedSolomonException {
59	    decodeWithECCount(received, twoS);
60	  }
61	
62	  /**
63	   * <p>Decodes given set of received codewords, which include both data and error-correction
64	   * codewords. Really, this means it uses Reed-Solomon to detect and correct errors, in-place,
65	   * in the input.</p>
66	   *
67	   * @param received data and error-correction codewords
68	   * @param twoS number of error-correction codewords available
69	   * @return the number of errors corrected
70	   * @throws ReedSolomonException if decoding fails for any reason
71	   */
72	  public int decodeWithECCount(int[] received, int twoS) throws ReedSolomonException {
73	    GenericGFPoly poly = new GenericGFPoly(field, received);
74	    int[] syndromeCoefficients = new int[twoS];
75	    boolean noError = true;
76	    for (int i = 0; i < twoS; i++) {
77	      int eval = poly.evaluateAt(field.exp(i + field.getGeneratorBase()));
78	      syndromeCoefficients[syndromeCoefficients.length - 1 - i] = eval;
79	      if (eval != 0) {
80	        noError = false;
81	      }
82	    }
83	    if (noError) {
84	      return 0;
85	    }
86	    GenericGFPoly syndrome = new GenericGFPoly(field, syndromeCoefficients);
87	    GenericGFPoly[] sigmaOmega =
88	        runEuclideanAlgorithm(field.buildMonomial(twoS, 1), syndrome, twoS);
89	    GenericGFPoly sigma = sigmaOmega[0];
90	    GenericGFPoly omega = sigmaOmega[1];
91	    int[] errorLocations = findErrorLocations(sigma);
92	    int[] errorMagnitudes = findErrorMagnitudes(omega, errorLocations);
93	    for (int i = 0; i < errorLocations.length; i++) {
94	      int position = received.length - 1 - field.log(errorLocations[i]);
95	      if (position < 0) {
96	        throw new ReedSolomonException("Bad error location");
97	      }
98	      received[position] = GenericGF.addOrSubtract(received[position], errorMagnitudes[i]);
99	    }
100	    return errorLocations.length;
101	  }
102	
103	  private GenericGFPoly[] runEuclideanAlgorithm(GenericGFPoly a, GenericGFPoly b, int R)
104	      throws ReedSolomonException {
105	    // Assume a's degree is >= b's
106	    if (a.getDegree() < b.getDegree()) {
107	      GenericGFPoly temp = a;
108	      a = b;
109	      b = temp;
110	    }
111	
112	    GenericGFPoly rLast = a;
113	    GenericGFPoly r = b;
114	    GenericGFPoly tLast = field.getZero();
115	    GenericGFPoly t = field.getOne();
116	
117	    // Run Euclidean algorithm until r's degree is less than R/2
118	    while (2 * r.getDegree() >= R) {
119	      GenericGFPoly rLastLast = rLast;
120	      GenericGFPoly tLastLast = tLast;
121	      rLast = r;
122	      tLast = t;
123	
124	      // Divide rLastLast by rLast, with quotient in q and remainder in r
125	      if (rLast.isZero()) {
126	        // Oops, Euclidean algorithm already terminated?
127	        throw new ReedSolomonException("r_{i-1} was zero");
128	      }
129	      r = rLastLast;
130	      GenericGFPoly q = field.getZero();
131	      int denominatorLeadingTerm = rLast.getCoefficient(rLast.getDegree());
132	      int dltInverse = field.inverse(denominatorLeadingTerm);
133	      while (r.getDegree() >= rLast.getDegree() && !r.isZero()) {
134	        int degreeDiff = r.getDegree() - rLast.getDegree();
135	        int scale = field.multiply(r.getCoefficient(r.getDegree()), dltInverse);
136	        q = q.addOrSubtract(field.buildMonomial(degreeDiff, scale));
137	        r = r.addOrSubtract(rLast.multiplyByMonomial(degreeDiff, scale));
138	      }
139	
140	      t = q.multiply(tLast).addOrSubtract(tLastLast);
141	
142	      if (r.getDegree() >= rLast.getDegree()) {
143	        throw new IllegalStateException("Division algorithm failed to reduce polynomial? " +
144	          "r: " + r + ", rLast: " + rLast);
145	      }
146	    }
147	
148	    int sigmaTildeAtZero = t.getCoefficient(0);
149	    if (sigmaTildeAtZero == 0) {
150	      throw new ReedSolomonException("sigmaTilde(0) was zero");
151	    }
152	
153	    int inverse = field.inverse(sigmaTildeAtZero);
154	    GenericGFPoly sigma = t.multiply(inverse);
155	    GenericGFPoly omega = r.multiply(inverse);
156	    return new GenericGFPoly[]{sigma, omega};
157	  }
158	
159	  private int[] findErrorLocations(GenericGFPoly errorLocator) throws ReedSolomonException {
160	    // This is a direct application of Chien's search
161	    int numErrors = errorLocator.getDegree();
162	    if (numErrors == 1) { // shortcut
163	      return new int[] { errorLocator.getCoefficient(1) };
164	    }
165	    int[] result = new int[numErrors];
166	    int e = 0;
167	    for (int i = 1; i < field.getSize() && e < numErrors; i++) {
168	      if (errorLocator.evaluateAt(i) == 0) {
169	        result[e] = field.inverse(i);
170	        e++;
171	      }
172	    }
173	    if (e != numErrors) {
174	      throw new ReedSolomonException("Error locator degree does not match number of roots");
175	    }
176	    return result;
177	  }
178	
179	  private int[] findErrorMagnitudes(GenericGFPoly errorEvaluator, int[] errorLocations) {
180	    // This is directly applying Forney's Formula
181	    int s = errorLocations.length;
182	    int[] result = new int[s];
183	    for (int i = 0; i < s; i++) {
184	      int xiInverse = field.inverse(errorLocations[i]);
185	      int denominator = 1;
186	      for (int j = 0; j < s; j++) {
187	        if (i != j) {
188	          //denominator = field.multiply(denominator,
189	          //    GenericGF.addOrSubtract(1, field.multiply(errorLocations[j], xiInverse)));
190	          // Above should work but fails on some Apple and Linux JDKs due to a Hotspot bug.
191	          // Below is a funny-looking workaround from Steven Parkes
192	          int term = field.multiply(errorLocations[j], xiInverse);
193	          int termPlus1 = (term & 0x1) == 0 ? term | 1 : term & ~1;
194	          denominator = field.multiply(denominator, termPlus1);
195	        }
196	      }
197	      result[i] = field.multiply(errorEvaluator.evaluateAt(xiInverse),
198	          field.inverse(denominator));
199	      if (field.getGeneratorBase() != 0) {
200	        result[i] = field.multiply(result[i], xiInverse);
201	      }
202	    }
203	    return result;
204	  }
