23	/**
24	 * This class implements a local thresholding algorithm, which while slower than the
25	 * GlobalHistogramBinarizer, is fairly efficient for what it does. It is designed for
26	 * high frequency images of barcodes with black data on white backgrounds. For this application,
27	 * it does a much better job than a global blackpoint with severe shadows and gradients.
28	 * However it tends to produce artifacts on lower frequency images and is therefore not
29	 * a good general purpose binarizer for uses outside ZXing.
30	 *
31	 * This class extends GlobalHistogramBinarizer, using the older histogram approach for 1D readers,
32	 * and the newer local approach for 2D readers. 1D decoding using a per-row histogram is already
33	 * inherently local, and only fails for horizontal gradients. We can revisit that problem later,
34	 * but for now it was not a win to use local blocks for 1D.
35	 *
36	 * This Binarizer is the default for the unit tests and the recommended class for library users.
37	 *
38	 * @author dswitkin@google.com (Daniel Switkin)
39	 */
40	public final class HybridBinarizer extends GlobalHistogramBinarizer {
41	
42	  // This class uses 5x5 blocks to compute local luminance, where each block is 8x8 pixels.
43	  // So this is the smallest dimension in each axis we can accept.
44	  private static final int BLOCK_SIZE_POWER = 3;
45	  private static final int BLOCK_SIZE = 1 << BLOCK_SIZE_POWER; // ...0100...00
46	  private static final int BLOCK_SIZE_MASK = BLOCK_SIZE - 1;   // ...0011...11
47	  private static final int BLOCK_SIZE_GRID = 5;
48	  private static final int BLOCK_SIZE_GRID_AREA = BLOCK_SIZE_GRID * BLOCK_SIZE_GRID; // 25
49	  private static final int MINIMUM_DIMENSION = BLOCK_SIZE * BLOCK_SIZE_GRID;
50	  private static final int MIN_DYNAMIC_RANGE = 24;
51	
52	  private BitMatrix matrix;
53	
54	  public HybridBinarizer(LuminanceSource source) {
55	    super(source);
56	  }
57	
58	  /**
59	   * Calculates the final BitMatrix once for all requests. This could be called once from the
60	   * constructor instead, but there are some advantages to doing it lazily, such as making
61	   * profiling easier, and not doing heavy lifting when callers don't expect it.
62	   */
63	  @Override
64	  public BitMatrix getBlackMatrix() throws NotFoundException {
65	    if (matrix != null) {
66	      return matrix;
67	    }
68	    LuminanceSource source = getLuminanceSource();
69	    int width = source.getWidth();
70	    int height = source.getHeight();
71	    if (width >= MINIMUM_DIMENSION && height >= MINIMUM_DIMENSION) {
72	      byte[] luminances = source.getMatrix();
73	      int subWidth = (width + BLOCK_SIZE_MASK) >> BLOCK_SIZE_POWER;
74	      int subHeight = (height + BLOCK_SIZE_MASK) >> BLOCK_SIZE_POWER;
75	      int[][] blackPoints = calculateBlackPoints(luminances, subWidth, subHeight, width, height);
76	
77	      BitMatrix newMatrix = new BitMatrix(width, height);
78	      calculateThresholdForBlock(luminances, subWidth, subHeight, width, height, blackPoints, newMatrix);
79	      matrix = newMatrix;
80	    } else {
81	      // If the image is too small, fall back to the global histogram approach.
82	      matrix = super.getBlackMatrix();
83	    }
84	    return matrix;
85	  }
86	
87	  @Override
88	  public Binarizer createBinarizer(LuminanceSource source) {
89	    return new HybridBinarizer(source);
90	  }
91	
92	  /**
93	   * For each block in the image, calculate the average black point using a 5x5 grid
94	   * of the blocks around it. Also handles the corner cases (fractional blocks are computed based
95	   * on the last pixels in the row/column which are also used in the previous block).
96	   */
97	  private static void calculateThresholdForBlock(byte[] luminances,
98	                                                 int subWidth,
99	                                                 int subHeight,
100	                                                 int width,
101	                                                 int height,
102	                                                 int[][] blackPoints,
103	                                                 BitMatrix matrix) {
104	    int maxYOffset = height - BLOCK_SIZE;
105	    int maxXOffset = width - BLOCK_SIZE;
106	    for (int y = 0; y < subHeight; y++) {
107	      int yoffset = y << BLOCK_SIZE_POWER;
108	      if (yoffset > maxYOffset) {
109	        yoffset = maxYOffset;
110	      }
111	      int top = cap(y, subHeight - 3);
112	      for (int x = 0; x < subWidth; x++) {
113	        int xoffset = x << BLOCK_SIZE_POWER;
114	        if (xoffset > maxXOffset) {
115	          xoffset = maxXOffset;
116	        }
117	        int left = cap(x, subWidth - 3);
118	        int sum = 0;
119	        for (int z = -2; z <= 2; z++) {
120	          int[] blackRow = blackPoints[top + z];
121	          sum += blackRow[left - 2] + blackRow[left - 1] + blackRow[left] + blackRow[left + 1] + blackRow[left + 2];
122	        }
123	        int average = sum / BLOCK_SIZE_GRID_AREA;
124	        thresholdBlock(luminances, xoffset, yoffset, average, width, matrix);
125	      }
126	    }
127	  }
128	
129	  private static int cap(int value, int max) {
130	    return value < 2 ? 2 : Math.min(value, max);
131	  }
132	
133	  /**
134	   * Applies a single threshold to a block of pixels.
135	   */
136	  private static void thresholdBlock(byte[] luminances,
137	                                     int xoffset,
138	                                     int yoffset,
139	                                     int threshold,
140	                                     int stride,
141	                                     BitMatrix matrix) {
142	    for (int y = 0, offset = yoffset * stride + xoffset; y < BLOCK_SIZE; y++, offset += stride) {
143	      for (int x = 0; x < BLOCK_SIZE; x++) {
144	        // Comparison needs to be <= so that black == 0 pixels are black even if the threshold is 0.
145	        if ((luminances[offset + x] & 0xFF) <= threshold) {
146	          matrix.set(xoffset + x, yoffset + y);
147	        }
148	      }
149	    }
150	  }
151	
152	  /**
153	   * Calculates a single black point for each block of pixels and saves it away.
154	   * See the following thread for a discussion of this algorithm:
155	   *  http://groups.google.com/group/zxing/browse_thread/thread/d06efa2c35a7ddc0
156	   */
157	  private static int[][] calculateBlackPoints(byte[] luminances,
158	                                              int subWidth,
159	                                              int subHeight,
160	                                              int width,
161	                                              int height) {
162	    int maxYOffset = height - BLOCK_SIZE;
163	    int maxXOffset = width - BLOCK_SIZE;
164	    int[][] blackPoints = new int[subHeight][subWidth];
165	    for (int y = 0; y < subHeight; y++) {
166	      int yoffset = y << BLOCK_SIZE_POWER;
167	      if (yoffset > maxYOffset) {
168	        yoffset = maxYOffset;
169	      }
170	      for (int x = 0; x < subWidth; x++) {
171	        int xoffset = x << BLOCK_SIZE_POWER;
172	        if (xoffset > maxXOffset) {
173	          xoffset = maxXOffset;
174	        }
175	        int sum = 0;
176	        int min = 0xFF;
177	        int max = 0;
178	        for (int yy = 0, offset = yoffset * width + xoffset; yy < BLOCK_SIZE; yy++, offset += width) {
179	          for (int xx = 0; xx < BLOCK_SIZE; xx++) {
180	            int pixel = luminances[offset + xx] & 0xFF;
181	            sum += pixel;
182	            // still looking for good contrast
183	            if (pixel < min) {
184	              min = pixel;
185	            }
186	            if (pixel > max) {
187	              max = pixel;
188	            }
189	          }
190	          // short-circuit min/max tests once dynamic range is met
191	          if (max - min > MIN_DYNAMIC_RANGE) {
192	            // finish the rest of the rows quickly
193	            for (yy++, offset += width; yy < BLOCK_SIZE; yy++, offset += width) {
194	              for (int xx = 0; xx < BLOCK_SIZE; xx++) {
195	                sum += luminances[offset + xx] & 0xFF;
196	              }
197	            }
198	          }
199	        }
200	
201	        // The default estimate is the average of the values in the block.
202	        int average = sum >> (BLOCK_SIZE_POWER * 2);
203	        if (max - min <= MIN_DYNAMIC_RANGE) {
204	          // If variation within the block is low, assume this is a block with only light or only
205	          // dark pixels. In that case we do not want to use the average, as it would divide this
206	          // low contrast area into black and white pixels, essentially creating data out of noise.
207	          //
208	          // The default assumption is that the block is light/background. Since no estimate for
209	          // the level of dark pixels exists locally, use half the min for the block.
210	          average = min / 2;
211	
212	          if (y > 0 && x > 0) {
213	            // Correct the "white background" assumption for blocks that have neighbors by comparing
214	            // the pixels in this block to the previously calculated black points. This is based on
215	            // the fact that dark barcode symbology is always surrounded by some amount of light
216	            // background for which reasonable black point estimates were made. The bp estimated at
217	            // the boundaries is used for the interior.
218	
219	            // The (min < bp) is arbitrary but works better than other heuristics that were tried.
220	            int averageNeighborBlackPoint =
221	                (blackPoints[y - 1][x] + (2 * blackPoints[y][x - 1]) + blackPoints[y - 1][x - 1]) / 4;
222	            if (min < averageNeighborBlackPoint) {
223	              average = averageNeighborBlackPoint;
224	            }
225	          }
226	        }
227	        blackPoints[y][x] = average;
228	      }
229	    }
230	    return blackPoints;
231	  }
